using ETulongData;using ETulong;using ETulongDesktop;using Microsoft.EntityFrameworkCore;using Npgsql;using System.Net;using System.Net.Http.Json;using Xunit;using Xunit.Abstractions;
namespace ETulongTests;
public sealed class AcceptanceTests(ITestOutputHelper output):ApiFixture(output) {
 [Fact]public async Task FP01_IntakeDocumentsSubmissionAndRetry(){await Call<CaseDetail>("POST","cases",400,new DraftInput("","","",null,2),unchanged:true);var c=await Draft("INTAKE",attach:false);await using(var d=Db()){Assert.Equal(0,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);Assert.Empty(await d.Reservations.ToArrayAsync());}await Action(c.Id,"submit",expected:409,unchanged:true);await Action(c.Id,"documents",new DocumentInput(c.Requirements[0].Id,"bad.txt",[1,2,3]),expected:400,unchanged:true);foreach(var r in c.Requirements)c=(await Action(c.Id,"documents",new DocumentInput(r.Id,"fixture.png",Png)))!;var vm=new MainVm(new DeskClient(Http));await vm.RefreshCommand.ExecuteAsync(null);vm.SelectedCase=Assert.Single(vm.Cases,x=>x.Id==c.Id);await vm.OpenCommand.ExecuteAsync(null);vm.SelectedRequirement=vm.Requirements[0];vm.PickDocumentAsync=()=>Task.FromResult<(string Name,byte[] Bytes)?>( ("viewmodel-fixture.png",Png) );await vm.AttachCommand.ExecuteAsync(null);Assert.Contains("Document saved",vm.Message);Assert.Equal(3,vm.Documents.Length);var pickerBefore=await State();vm.PickDocumentAsync=()=>Task.FromResult<(string Name,byte[] Bytes)?>(null);await vm.AttachCommand.ExecuteAsync(null);Assert.Equal("Document selection cancelled.",vm.Message);Assert.Equal(pickerBefore,await State());var submitted=(await Action(c.Id,"submit"))!;Assert.Equal("Submitted",submitted.Status);Assert.Equal("Reserved",submitted.ReservationState);Assert.NotNull(submitted.SubmittedAt);await Action(c.Id,"submit",unchanged:true);await Call<CaseDetail>("POST","cases",409,new DraftInput("DEMO-INTAKE","Applicant INTAKE","Demo Barangay",null,2),unchanged:true);await using(var d=Db()){Assert.Equal(1,await d.Reservations.CountAsync());Assert.Equal(1,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);Assert.Equal(3,await d.Documents.CountAsync());}}
 [Fact]public async Task FP02_TwoApplicantsCompeteForLastSlot(){var a=await Draft("RACE-A");var b=await Draft("RACE-B");await using var gate=new NpgsqlConnection(Connection);await gate.OpenAsync();await using var tx=await gate.BeginTransactionAsync();await using(var command=new NpgsqlCommand("SELECT 1 FROM \"AssistanceBatches\" WHERE \"Id\"=2 FOR UPDATE",gate,tx))await command.ExecuteScalarAsync();
  using var first=new HttpClient{BaseAddress=Http.BaseAddress,Timeout=TimeSpan.FromSeconds(15)};using var second=new HttpClient{BaseAddress=Http.BaseAddress,Timeout=TimeSpan.FromSeconds(15)};first.DefaultRequestHeaders.Add("X-Demo-Staff","1");second.DefaultRequestHeaders.Add("X-Demo-Staff","1");var r1=first.PostAsync($"api/cases/{a.Id}/submit",null);var r2=second.PostAsync($"api/cases/{b.Id}/submit",null);var blocked=0;
  try{for(int i=0;i<60;i++){await using var observe=new NpgsqlConnection(Connection);await observe.OpenAsync();await using var count=new NpgsqlCommand("SELECT count(*) FROM pg_stat_activity WHERE datname=current_database() AND wait_event_type='Lock' AND query LIKE 'UPDATE%AssistanceBatches%'",observe);blocked=Convert.ToInt32(await count.ExecuteScalarAsync());if(blocked>=2)break;await Task.Delay(50);}Assert.True(blocked>=2,"Both independent HTTP requests must reach the database capacity lock before it is released.");}finally{await tx.CommitAsync();}
  var responses=await Task.WhenAll(r1,r2);try{Assert.Equal(new[]{200,409},responses.Select(x=>(int)x.StatusCode).Order());foreach(var r in responses)Output.WriteLine("Concurrent actual HTTP result: "+(int)r.StatusCode+" "+await r.Content.ReadAsStringAsync());}finally{foreach(var r in responses)r.Dispose();}
  await using(var d=Db()){Assert.Equal(1,await d.Reservations.CountAsync());Assert.Equal(1,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);Assert.Equal(1,await d.Applications.CountAsync(x=>x.Status=="Submitted"));Assert.Equal(1,await d.Applications.CountAsync(x=>x.Status=="Draft"));var winner=await d.Reservations.AsNoTracking().SingleAsync();var before=await State();var duplicate=await Assert.ThrowsAsync<PostgresException>(()=>Sql($"INSERT INTO \"Reservations\" (\"CaseId\",\"BatchId\",\"State\",\"CreatedAt\") VALUES ({winner.CaseId},2,'Reserved',now())"));Assert.Equal("23505",duplicate.SqlState);Assert.Equal(before,await State());}Output.WriteLine("Two genuine blocked capacity updates observed; exactly one reservation, no overbooking.");}
 [Fact]public async Task FP03_ReviewReplacementAndEndorsementRules(){var c=await Draft("REVIEW",1);c=(await Action(c.Id,"submit"))!;await Action(c.Id,"endorse",expected:409,unchanged:true);var doc=c.Documents[0];await Action(c.Id,"review",new ReviewInput(doc.Id,"Resubmit",""),expected:400,unchanged:true);c=(await Action(c.Id,"review",new ReviewInput(doc.Id,"Resubmit","Image needs replacement")))!;Assert.Equal("NeedsResubmission",c.Status);c=(await Action(c.Id,"documents",new DocumentInput(doc.RequirementId,"replacement.png",Png)))!;var replacement=Assert.Single(c.Documents,x=>x.Id==doc.Id);Assert.Equal("Pending",replacement.Decision);Assert.Null(replacement.Reviewer);foreach(var item in c.Documents)c=(await Action(c.Id,"review",new ReviewInput(item.Id,"Accepted","Manual review complete")))!;c=(await Action(c.Id,"endorse"))!;Assert.Equal("Endorsed",c.Status);Assert.All(c.Documents,x=>{Assert.Equal("Accepted",x.Decision);Assert.NotNull(x.Reviewer);});await Action(c.Id,"decision",new DecisionInput(true,"Wrong role"),expected:403,actor:1,unchanged:true);await Action(c.Id,"documents",new DocumentInput(doc.RequirementId,"late.png",Png),expected:409,unchanged:true);}
 [Fact]public async Task FP04_OfficialDecisionAndDenialFreeCapacity(){var c=await Endorsed("DENY",2);await Action(c.Id,"decision",new DecisionInput(false,""),expected:400,actor:2,unchanged:true);var denied=(await Action(c.Id,"decision",new DecisionInput(false,"Does not meet office requirements"),actor:2))!;Assert.Equal("Denied",denied.Status);Assert.Equal("Released",denied.ReservationState);Assert.Equal("Approving official",denied.Approval!.Official);await Action(c.Id,"schedule",new ScheduleInput(D),expected:409,unchanged:true);await Action(c.Id,"decision",new DecisionInput(false,"repeat"),expected:409,actor:2,unchanged:true);await using(var d=Db())Assert.Equal(0,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);var next=await Endorsed("APPROVE",2);var approved=(await Action(next.Id,"decision",new DecisionInput(true,"Official decision recorded"),actor:2))!;Assert.Equal("Approved",approved.Status);Assert.Equal("Awarded",approved.ReservationState);await using(var d=Db()){Assert.Equal(1,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);Assert.Equal(2,await d.Approvals.CountAsync());}}
 [Fact]public async Task FP05_ClaimHoldResolutionAndSingleRelease(){var c=await Scheduled("CLAIM");await Action(c.Id,"verify",new VerificationInput(false,""),expected:400,actor:3,unchanged:true);var held=(await Action(c.Id,"verify",new VerificationInput(false,"ID on original does not match uploaded copy"),actor:3))!;Assert.Equal("Held",held.Status);Assert.Equal("Held",Assert.Single(held.Verifications).Result);await Action(c.Id,"verify",new VerificationInput(true,"All originals now match"),expected:409,actor:3,unchanged:true);var released=(await Action(c.Id,"verify",new VerificationInput(true,"Hold resolved; all originals manually verified",true),actor:3))!;Assert.Equal("Released",released.Status);Assert.Equal(new[]{"Held","Released"},released.Verifications.Select(x=>x.Result));await Action(c.Id,"verify",new VerificationInput(true,"Duplicate release",true),expected:409,actor:3,unchanged:true);await using var d=Db();Assert.Equal("Released",(await d.Applications.AsNoTracking().SingleAsync(x=>x.Id==c.Id)).Status);Assert.Equal(1,await d.Verifications.CountAsync(x=>x.CaseId==c.Id&&x.Result=="Released"));Assert.Equal("Awarded",(await d.Reservations.AsNoTracking().SingleAsync(x=>x.CaseId==c.Id)).State);}
 [Fact]public async Task FP06_PostWriteFailuresRollbackCapacityAndRelease(){var c=await Draft("ROLLBACK");var before=await State();await Start(true);await Action(c.Id,"submit",expected:500,unchanged:true);Assert.Contains("ETULONG_POST_WRITE_FAULT after actual SaveChanges",Log.ToString());Assert.Equal(before,await State());await Start();await Action(c.Id,"submit");await using(var d=Db()){Assert.Equal(1,await d.Reservations.CountAsync());Assert.Equal(1,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);}var scheduled=await Scheduled("RELEASE-ROLLBACK");before=await State();await Start(true);await Action(scheduled.Id,"verify",new VerificationInput(true,"Valid verification"),expected:500,actor:3,unchanged:true);Assert.Equal(before,await State());await Start();var release=(await Action(scheduled.Id,"verify",new VerificationInput(true,"Valid verification"),actor:3))!;Assert.Equal("Released",release.Status);}
 [Fact]public async Task FP07_FreshContextsImagesAndActualApiRestart(){var c=await Scheduled("PERSIST");c=(await Action(c.Id,"verify",new VerificationInput(true,"Manually checked"),actor:3))!;var before=await State();await using(var d=Db()){Assert.Equal("Released",(await d.Applications.AsNoTracking().SingleAsync(x=>x.Id==c.Id)).Status);Assert.Equal(Png,(await d.Documents.AsNoTracking().OrderBy(x=>x.Id).FirstAsync()).Content);}await Start();var after=(await Call<CaseDetail>("GET",$"cases/{c.Id}",200,unchanged:true))!;Assert.Equal(c.Status,after.Status);Assert.Equal(c.Applicant.Reference,after.Applicant.Reference);Assert.Equal(c.SubmittedAt,after.SubmittedAt);Assert.Equal(c.ClaimDate,after.ClaimDate);Assert.Equal(c.Approval,after.Approval);Assert.Equal(c.Documents,after.Documents);Assert.Equal(c.Verifications,after.Verifications);Assert.Equal(before,await State());Assert.Equal(Png,await Http.GetByteArrayAsync($"api/documents/{c.Documents[0].Id}/image"));await using(var d=Db()){await d.Database.MigrateAsync();await Seed.Run(d);}Assert.Equal(before,await State());Output.WriteLine("New API process plus fresh PostgreSQL contexts retain operational data; rerunning initialization does not reset cases.");}
 sealed class Handler(Func<HttpRequestMessage,Task<HttpResponseMessage>> action):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken ct){Calls++;return action(request);}}
 [Fact]public async Task FP08_ProtocolTransportAndLostAcknowledgement(){await Call<CaseDetail>("POST","cases",403,new DraftInput("X","Name","Area",null,1),actor:99,unchanged:true);await Call<CaseDetail>("POST","cases",400,new{applicantReference="MISSING"},unchanged:true);await Call<CaseDetail>("GET","cases/999999",404,unchanged:true);using(var handler=new Handler(_=>throw new HttpRequestException("Controlled unreachable")))using(var http=new HttpClient(handler){BaseAddress=Http.BaseAddress}){var client=new DeskClient(http);var ex=await Assert.ThrowsAsync<Exception>(()=>client.Reference());Assert.Contains("No HTTP response",ex.Message);Assert.Equal(1,handler.Calls);}var c=await Draft("ACK-LOSS");using(var handler=new Handler(async request=>{using var forward=new HttpRequestMessage(request.Method,request.RequestUri){Content=request.Content};forward.Headers.Add("X-Demo-Staff","1");using var response=await Http.SendAsync(forward);Assert.Equal(HttpStatusCode.OK,response.StatusCode);throw new HttpRequestException("Response lost AFTER real commit");}))using(var http=new HttpClient(handler){BaseAddress=Http.BaseAddress}){var client=new DeskClient(http);var ex=await Assert.ThrowsAsync<Exception>(()=>client.Action(c.Id,"submit"));Assert.Contains("unknown",ex.Message);Assert.Contains("verify",ex.Message,StringComparison.OrdinalIgnoreCase);Assert.Equal(1,handler.Calls);await using var d=Db();Assert.Equal(1,await d.Reservations.CountAsync(x=>x.CaseId==c.Id));Assert.Equal(1,(await d.Batches.AsNoTracking().SingleAsync(x=>x.Id==2)).ReservedCount);}await Action(c.Id,"submit",unchanged:true);Output.WriteLine("Actual committed submission; simulated response loss; no automatic retry; independent PG verified; explicit retry reused the reservation.");}
}

